<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';
require_once __DIR__.'/../_helper.php';
uks_require_access($pdo);
if(!uks_can_manage($pdo)) deny_access();
$q=trim((string)($_GET['q']??''));
$stockFilter=(string)($_GET['stock']??'');
$expiryFilter=(string)($_GET['expiry']??'');
$per=(int)($_GET['per_page']??20);$per=in_array($per,[10,20,50,100],true)?$per:20;
$page=max(1,(int)($_GET['page']??1));
$where=['1=1'];$params=[];
if($q!==''){ $where[]='(kode LIKE ? OR nama LIKE ? OR lokasi LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like); }
if($stockFilter==='low') $where[]='aktif=1 AND stok_saat_ini<=stok_minimum';
if($stockFilter==='available') $where[]='stok_saat_ini>0';
if($stockFilter==='empty') $where[]='stok_saat_ini=0';
if($expiryFilter==='expired') $where[]="tanggal_kadaluarsa IS NOT NULL AND tanggal_kadaluarsa<CURDATE()";
if($expiryFilter==='30') $where[]="tanggal_kadaluarsa IS NOT NULL AND tanggal_kadaluarsa>=CURDATE() AND tanggal_kadaluarsa<=DATE_ADD(CURDATE(),INTERVAL 30 DAY)";
if($expiryFilter==='90') $where[]="tanggal_kadaluarsa IS NOT NULL AND tanggal_kadaluarsa>DATE_ADD(CURDATE(),INTERVAL 30 DAY) AND tanggal_kadaluarsa<=DATE_ADD(CURDATE(),INTERVAL 90 DAY)";
$c=$pdo->prepare('SELECT COUNT(*) FROM uks_obat WHERE '.implode(' AND ',$where));$c->execute($params);$total=(int)$c->fetchColumn();
$pages=max(1,(int)ceil($total/max(1,$per)));if($page>$pages)$page=$pages;$offset=($page-1)*$per;
$st=$pdo->prepare('SELECT * FROM uks_obat WHERE '.implode(' AND ',$where).' ORDER BY nama LIMIT '.$per.' OFFSET '.$offset);$st->execute($params);$rows=$st->fetchAll();
function obat_q(array $c=[]):string{$b=$_GET??[];unset($b['page']);foreach($c as $k=>$v){if($v===null)unset($b[$k]);else$b[$k]=$v;}return http_build_query($b);}
$page_title='Stok Obat UKS';require_once __DIR__.'/../../layouts/header.php';require_once __DIR__.'/../../layouts/sidebar.php';
?>
<main class="main uks-module-page"><header class="topbar"><div class="topbar-title">Stok Obat UKS</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content">
<style>.stock-hero{background:linear-gradient(135deg,#07111f,#12324a);color:#fff;border-radius:18px;padding:22px;margin-bottom:18px}.stock-card{background:#fff;border:1px solid #e2e8f0;border-radius:15px;padding:18px;margin-bottom:18px}.stock-badge{display:inline-flex;padding:4px 8px;border-radius:7px;font-size:11px;font-weight:800}.stock-danger{background:#fee2e2;color:#b91c1c}.stock-warning{background:#fef3c7;color:#92400e}.stock-success{background:#dcfce7;color:#166534}.stock-secondary{background:#e2e8f0;color:#475569}.stock-filter{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.stock-filter label{margin:0}.stock-filter .form-control{min-width:150px}</style>
<div class="stock-hero"><h1 style="margin:0;font-size:24px;font-weight:900"><i class="bi bi-capsule"></i> Stok Obat UKS</h1><p style="margin:6px 0 0;color:#cbd5e1">Kelola persediaan, stok minimum, dan tanggal kedaluwarsa obat.</p></div>
<div class="stock-card"><form method="get" class="stock-filter"><label><span class="form-label">Cari</span><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Kode / nama / lokasi"></label><label><span class="form-label">Stok</span><select class="form-control" name="stock"><option value="">Semua</option><option value="low" <?=$stockFilter==='low'?'selected':''?>>Menipis</option><option value="available" <?=$stockFilter==='available'?'selected':''?>>Tersedia</option><option value="empty" <?=$stockFilter==='empty'?'selected':''?>>Habis</option></select></label><label><span class="form-label">Kedaluwarsa</span><select class="form-control" name="expiry"><option value="">Semua</option><option value="expired" <?=$expiryFilter==='expired'?'selected':''?>>Kedaluwarsa</option><option value="30" <?=$expiryFilter==='30'?'selected':''?>>≤ 30 hari</option><option value="90" <?=$expiryFilter==='90'?'selected':''?>>31–90 hari</option></select></label><label><span class="form-label">Per Halaman</span><select class="form-control" name="per_page"><?php foreach([10,20,50,100] as $n):?><option value="<?=$n?>" <?=$per===$n?'selected':''?>><?=$n?></option><?php endforeach;?></select></label><button class="btn btn-primary"><i class="bi bi-search"></i> Tampilkan</button><a class="btn btn-secondary" href="<?=BASE_URL?>uks/obat/index.php">Reset</a></form></div>
<div class="stock-card"><div class="page-header" style="padding:0;margin:0 0 14px"><div><h2 style="font-size:16px;margin:0;font-weight:900">Daftar Obat</h2><p style="margin:4px 0 0;color:#64748b;font-size:12px"><?=number_format($total)?> data sesuai filter.</p></div><div class="page-header-actions"><a class="btn btn-secondary" href="<?=BASE_URL?>uks/index.php"><i class="bi bi-arrow-left"></i> UKS</a><a class="btn btn-primary" href="<?=BASE_URL?>uks/obat/tambah.php"><i class="bi bi-plus-circle"></i> Tambah Obat</a></div></div>
<div class="table-responsive"><table class="data-table"><thead><tr><th>Kode</th><th>Nama Obat</th><th>Stok</th><th>Minimum</th><th>Kedaluwarsa</th><th>Lokasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="empty-state">Tidak ada obat sesuai filter.</td></tr><?php else:foreach($rows as $r):$low=(int)$r['stok_saat_ini']<=(int)$r['stok_minimum'];$ex=uks_expiry_state($r['tanggal_kadaluarsa']??null);$cls='stock-'.$ex['class'];?><tr><td><?=e($r['kode'])?></td><td><strong><?=e($r['nama'])?></strong><div style="font-size:11px;color:#64748b"><?=e($r['satuan'])?></div></td><td><strong><?=number_format((int)$r['stok_saat_ini'])?></strong> <?php if($low):?><span class="stock-badge stock-danger">Menipis</span><?php endif;?></td><td><?=number_format((int)$r['stok_minimum'])?></td><td><?=e($r['tanggal_kadaluarsa']??'-')?> <?php if($ex['key']!=='none'):?><span class="stock-badge <?=$cls?>"><?=e($ex['label'])?></span><?php endif;?></td><td><?=e($r['lokasi']??'-')?></td><td><?=((int)$r['aktif']===1)?'Aktif':'Nonaktif'?></td><td><a class="btn btn-sm btn-primary" title="Edit" href="<?=BASE_URL?>uks/obat/edit.php?id=<?=$r['id']?>"><i class="bi bi-pencil-square"></i></a><a class="btn btn-sm btn-secondary" title="Kartu stok" href="<?=BASE_URL?>uks/obat/stok.php?id=<?=$r['id']?>"><i class="bi bi-box-seam"></i></a></td></tr><?php endforeach;endif;?></tbody></table></div><?php if($pages>1):?><div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px"><small>Halaman <?=$page?>/<?=$pages?></small><div style="display:flex;gap:5px;flex-wrap:wrap"><?php for($p=1;$p<=$pages;$p++):?><a class="btn btn-sm <?=$p===$page?'btn-primary':'btn-secondary'?>" href="?<?=e(obat_q(['page'=>$p]))?>"><?=$p?></a><?php endfor;?></div></div><?php endif;?></div></section></main><?php require_once __DIR__.'/../../layouts/footer.php';
